<?php $pageTitle='Schools';$active=count(array_filter($schools,static fn($s)=>$s['status']==='active'));$programmes=array_sum(array_map(static fn($s)=>(int)$s['programme_count'],$schools)); ?>
<div class="gov-page gov-enter"><section class="gov-hero"><div><div class="gov-brand"><img src="<?= e(url('assets/images/gbu-emblem.png')) ?>" alt="" width="44" height="44"><span>Gautam Buddha University<br><b>Academic master data</b></span></div><h1>University schools</h1><p>Maintain the academic ownership structure used by programmes, students, faculty, examinations, and reports.</p></div><div class="gov-hero-stat"><span class="gov-icon icon-school" aria-hidden="true"></span><strong><?= count($schools) ?></strong><small>schools in the directory</small></div></section><?php if($success):?><div class="alert success" role="status"><?= e($success) ?></div><?php endif;?><?php if($error):?><div class="alert error" role="alert"><?= e($error) ?></div><?php endif;?><section class="gov-metrics"><div><span>Total schools</span><strong><?= count($schools) ?></strong><small>University directory</small></div><div><span>Active schools</span><strong><?= $active ?></strong><small>Available in forms</small></div><div><span>Programme mappings</span><strong><?= $programmes ?></strong><small>Owned by schools</small></div></section>
<div class="master-workspace"><form class="master-create" method="post" action="<?= e(url('masters/schools')) ?>"><?= csrf_field() ?><header><span class="gov-icon icon-add" aria-hidden="true"></span><div><h2>Add university school</h2><p>Create an official academic owner.</p></div></header><label>School code<input name="code" placeholder="Example: SOICT" required><small>Use the official short code.</small></label><label>Official name<input name="name" placeholder="School of Information and Communication Technology" required></label><label>Short name<input name="short_name" placeholder="Information and Communication Technology"></label><button><span>Create school</span><b aria-hidden="true">→</b></button></form><section class="master-register"><header><div><h2>School directory</h2><p><?= count($schools) ?> records, ordered by official name.</p></div><label class="gov-search"><span class="gov-icon icon-search" aria-hidden="true"></span><input data-gov-search type="search" placeholder="Search schools" aria-label="Search schools"></label></header><?php if($schools):?><div class="school-list" data-gov-list><?php foreach($schools as $i=>$school):?><article data-gov-row data-search="<?= e(strtolower($school['code'].' '.$school['name'].' '.$school['short_name'])) ?>" style="--gov-order:<?= $i ?>"><div class="school-code"><span class="gov-icon icon-school" aria-hidden="true"></span><strong><?= e($school['code']) ?></strong></div><div><h3><?= e($school['name']) ?></h3><p><?= e($school['short_name']?:'No short name recorded') ?></p></div><div class="school-programmes"><strong><?= (int)$school['programme_count'] ?></strong><span>programmes</span></div><span class="gov-status <?= e($school['status']) ?>"><?= e(ucfirst($school['status'])) ?></span></article><?php endforeach;?><div class="gov-filter-empty" hidden><strong>No matching schools</strong><span>Try another code or name.</span></div></div><?php else:?><div class="gov-empty"><span class="gov-icon icon-school" aria-hidden="true"></span><h2>No schools created</h2><p>Add the first university school using the form.</p></div><?php endif;?></section></div></div>
<script>(()=>{const input=document.querySelector('[data-gov-search]'),rows=[...document.querySelectorAll('[data-gov-row]')],empty=document.querySelector('.gov-filter-empty');input?.addEventListener('input',()=>{const term=input.value.trim().toLowerCase();let shown=0;rows.forEach(row=>{const visible=row.dataset.search.includes(term);row.hidden=!visible;if(visible)shown++;});if(empty)empty.hidden=shown!==0;});})();</script>
